for key,slug in slugs.items():
 d=n[key];dest=SITE/slug;dest.mkdir(exist_ok=True)
 for f in [key+'.xlsx',key+'_Decision_Memo.pdf',key+'-Summary.png']:shutil.copy2(P/f,dest/f)
 if key=='Operating_Plan':keys=['revenue','ebitda','endingCash'];labels=['Full-year revenue','Full-year EBITDA','December cash'];chartname='Operating_Plan'
 elif key=='Fleet_Investment':keys=['keepPV','replacePV','leasePV'];labels=['Keep: present-value cost','Replace: present-value cost','Lease: present-value cost'];chartname='Fleet_Investment'
 else:keys=['minCash','fundingGap','endingCash'];labels=['Lowest funded cash','Peak hypothetical debt','Week 26 funded cash'];chartname='Cash_Working_Capital'
